import { apiClient } from "@/lib/api-client";
import { fetchPath, type LessonTitle, type PathDetail } from "@/lib/catalogue";

export type SkillRef = { id: number; name: string; slug: string };
export type ExerciseItem = { id: number; title: string; type: string };

export type ContentBlock = { type: string } & Record<string, unknown>;

export type LessonDetail = {
  id: number;
  title: string;
  slug: string;
  summary: string;
  content: { version?: number; blocks?: ContentBlock[] } | null;
  estimated_minutes: number | null;
  module_id: number;
  skills_taught: SkillRef[];
  exercises: ExerciseItem[];
};

export const fetchLesson = (id: number) => apiClient.get<LessonDetail>(`lessons/${id}/`);

export type LessonNav = {
  moduleTitle: string;
  previous: LessonTitle | null;
  next: LessonTitle | null;
};

/** Voisins d'une leçon dans son module (null si le module est introuvable). */
export function lessonNeighbours(
  path: PathDetail,
  moduleId: number,
  lessonId: number,
): LessonNav | null {
  const mod = path.modules.find((m) => m.id === moduleId);
  if (!mod) return null;
  const index = mod.lessons.findIndex((l) => l.id === lessonId);
  if (index === -1) return null;
  return {
    moduleTitle: mod.title,
    previous: mod.lessons[index - 1] ?? null,
    next: mod.lessons[index + 1] ?? null,
  };
}

export { fetchPath };
/**
 * Client API minimal, unique point de sortie vers le backend Django.
 *
 * Choix structurants (voir CLAUDE.md > Auth) :
 * - `credentials: "include"` pour que le cookie httpOnly de refresh circule ;
 * - l'access token reste en memoire (jamais en localStorage) et est injecte
 *   ici via `setAccessTokenProvider` (voir lib/session.ts).
 */

/** URL de base cote navigateur, surchargeable par variable d'environnement. */
export const API_BASE_URL =
  process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:8000/api";

/** URL de base cote serveur Next (SSR / server components, reseau Docker). */
export const INTERNAL_API_BASE_URL =
  process.env.INTERNAL_API_URL ?? API_BASE_URL;

export class ApiError extends Error {
  constructor(
    message: string,
    readonly status: number,
    readonly payload: unknown = null,
  ) {
    super(message);
    this.name = "ApiError";
  }
}

let accessTokenProvider: () => string | null = () => null;

/** Branche la source du jeton d'acces (le store d'auth, en memoire). */
export function setAccessTokenProvider(provider: () => string | null) {
  accessTokenProvider = provider;
}

type RequestOptions = Omit<RequestInit, "body"> & {
  body?: unknown;
  /** Force l'URL de base (utile depuis un server component). */
  baseUrl?: string;
};

async function request<T>(path: string, options: RequestOptions = {}): Promise<T> {
  const { body, baseUrl, headers, ...init } = options;
  const base = baseUrl ?? (typeof window === "undefined" ? INTERNAL_API_BASE_URL : API_BASE_URL);
  const url = `${base.replace(/\/$/, "")}/${path.replace(/^\//, "")}`;

  const token = accessTokenProvider();
  const response = await fetch(url, {
    ...init,
    credentials: "include",
    headers: {
      Accept: "application/json",
      ...(body === undefined ? {} : { "Content-Type": "application/json" }),
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
      ...headers,
    },
    ...(body === undefined ? {} : { body: JSON.stringify(body) }),
  });

  const payload = await parseBody(response);

  if (!response.ok) {
    throw new ApiError(
      `${response.status} ${response.statusText} sur ${path}`,
      response.status,
      payload,
    );
  }

  return payload as T;
}

async function parseBody(response: Response): Promise<unknown> {
  if (response.status === 204) return null;
  const contentType = response.headers.get("content-type") ?? "";
  if (!contentType.includes("application/json")) return response.text();
  try {
    return await response.json();
  } catch {
    return null;
  }
}

export const apiClient = {
  get: <T>(path: string, options?: RequestOptions) =>
    request<T>(path, { ...options, method: "GET" }),
  post: <T>(path: string, body?: unknown, options?: RequestOptions) =>
    request<T>(path, { ...options, method: "POST", body }),
  patch: <T>(path: string, body?: unknown, options?: RequestOptions) =>
    request<T>(path, { ...options, method: "PATCH", body }),
  delete: <T>(path: string, options?: RequestOptions) =>
    request<T>(path, { ...options, method: "DELETE" }),
};
"use client";

import { useQuery } from "@tanstack/react-query";
import Link from "next/link";

import { LessonBlocks } from "@/components/lesson-blocks";
import { fetchLesson, fetchPath, lessonNeighbours } from "@/lib/lessons";

export function LessonView({ pathSlug, lessonId }: { pathSlug: string; lessonId: number }) {
  const lesson = useQuery({ queryKey: ["lesson", lessonId], queryFn: () => fetchLesson(lessonId) });
  const path = useQuery({ queryKey: ["path", pathSlug], queryFn: () => fetchPath(pathSlug) });

  if (lesson.isPending) return <p role="status" className="p-8 text-content-muted">Chargement...</p>;
  if (lesson.isError) {
    return (
      <p role="alert" className="py-12 text-content-secondary">
        Impossible d&apos;afficher cette leçon (introuvable ou non accessible).
      </p>
    );
  }

  const data = lesson.data;
  const nav = path.data ? lessonNeighbours(path.data, data.module_id, data.id) : null;
  const href = (id: number) => `/catalogue/${pathSlug}/lecons/${id}`;

  return (
    <article className="py-12">
      <Link href={`/catalogue/${pathSlug}`} className="text-sm text-accent hover:underline">
        {nav ? `Retour au parcours · ${nav.moduleTitle}` : "Retour au parcours"}
      </Link>
      <h1 className="mt-3 text-3xl font-semibold text-content-primary">{data.title}</h1>
      {data.summary && <p className="mt-2 text-content-secondary">{data.summary}</p>}

      {data.skills_taught.length > 0 && (
        <section aria-label="Compétences enseignées" className="mt-4">
          <h2 className="text-sm font-semibold text-content-muted">Compétences enseignées</h2>
          <ul className="mt-1 flex flex-wrap gap-2">
            {data.skills_taught.map((s) => (
              <li key={s.id} className="rounded-full bg-surface-2 px-3 py-1 text-sm text-accent">
                {s.name}
              </li>
            ))}
          </ul>
        </section>
      )}

      <div className="mt-8">
        <LessonBlocks blocks={data.content?.blocks ?? []} />
      </div>

      <section aria-label="Exercices" className="mt-10">
        <h2 className="text-xl font-semibold text-content-primary">Exercices</h2>
        {data.exercises.length === 0 ? (
          <p className="mt-2 text-content-secondary">Aucun exercice pour cette leçon.</p>
        ) : (
          <ul className="mt-2 list-disc pl-6 text-content-secondary">
            {data.exercises.map((e) => (
              <li key={e.id}>{e.title}</li>
            ))}
          </ul>
        )}
      </section>

      {nav && (
        <nav aria-label="Navigation dans le module" className="mt-10 flex justify-between">
          {nav.previous ? (
            <Link href={href(nav.previous.id)} className="text-accent hover:underline">
              ← {nav.previous.title}
            </Link>
          ) : (
            <span />
          )}
          {nav.next && (
            <Link href={href(nav.next.id)} className="text-accent hover:underline">
              {nav.next.title} →
            </Link>
          )}
        </nav>
      )}
    </article>
  );
}
"use client";

import { notFound } from "next/navigation";
import { use } from "react";

import { AuthGuard } from "@/components/auth-guard";
import { LessonView } from "@/components/lesson-view";

type Props = { params: Promise<{ slug: string; id: string }> };

export default function LessonPage({ params }: Props) {
  const { slug, id } = use(params);
  const lessonId = Number(id);
  if (!Number.isInteger(lessonId) || lessonId <= 0) notFound();
  return (
    <AuthGuard>
      <LessonView pathSlug={slug} lessonId={lessonId} />
    </AuthGuard>
  );
}
